(function(root){
const svg=(inner,view='0 0 400 230',cls='')=>`<svg viewBox="${view}" class="${cls}" aria-hidden="true" xmlns="http://www.w3.org/2000/svg">${inner}</svg>`;
const eyes=(x,y)=>`<ellipse cx="${x-8}" cy="${y}" rx="3.2" ry="4.8" fill="#302452"/><ellipse cx="${x+8}" cy="${y}" rx="3.2" ry="4.8" fill="#302452"/><path d="M${x-7} ${y+11}q7 8 14 0" fill="none" stroke="#302452" stroke-width="3" stroke-linecap="round"/>`;
const star=(x,y,s=1,fill='#ffd15a')=>`<path d="M0-13 4-4 14-4 6 3 9 13 0 7-9 13-6 3-14-4-4-4Z" fill="${fill}" transform="translate(${x} ${y}) scale(${s})"/>`;
function car(x,y,color='#fc775c',num=''){return `<g transform="translate(${x} ${y})"><path d="M-58 10q0-25 22-26h47q27 0 36 26" fill="${color}" stroke="#443065" stroke-width="3"/><path d="M-33-16v-18q20-13 37 0v18" fill="#c1e8ff" stroke="#443065" stroke-width="3"/><rect x="-65" y="5" width="120" height="29" rx="14" fill="${color}" stroke="#443065" stroke-width="3"/><path d="M-62 27H52" stroke="#443065" stroke-width="8" stroke-linecap="round"/><ellipse cx="-35" cy="34" rx="12" ry="7" fill="#443065"/><ellipse cx="30" cy="34" rx="12" ry="7" fill="#443065"/><circle cx="35" cy="12" r="6" fill="#fff1a7"/><path d="M-36-32v-37q0-9 10-9" fill="none" stroke="#443065" stroke-width="3"/><path d="M-30 9q20 13 39 0" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round"/>${num?`<text x="-6" y="24" text-anchor="middle" fill="#302452" font-size="25" font-weight="900">${num}</text>`:''}</g>`;}
function clown(x,y,s=1,color='#ff9ab8'){return `<g transform="translate(${x} ${y}) scale(${s})"><path d="M-25 13q-15 20-9 42h68q7-22-9-42" fill="${color}"/><path d="M-17 44-30 69M17 44 30 69" stroke="#5943b5" stroke-width="13" stroke-linecap="round"/><ellipse cx="-32" cy="73" rx="16" ry="7" fill="#ffbf49"/><ellipse cx="32" cy="73" rx="16" ry="7" fill="#ffbf49"/><circle cx="-29" cy="-11" r="14" fill="#f58c38"/><circle cx="29" cy="-11" r="14" fill="#f58c38"/><circle cy="-12" r="29" fill="#fff2d9"/><path d="M-20-34 0-65 20-34Z" fill="#6acabb"/><circle cy="-64" r="7" fill="#ffcf60"/>${eyes(0,-18)}<circle cy="-7" r="8" fill="#ff605d"/><path d="M-12 23 0 29-12 35ZM12 23 0 29 12 35Z" fill="#5943b5"/><circle cy="44" r="4" fill="#fff6d8"/><path d="M-25 22-47 9M25 22 47 9" stroke="${color}" stroke-width="12" stroke-linecap="round"/></g>`;}
function shape(id,x=50,y=50,size=55,color){color=color||({circle:'#ffad47',triangle:'#ff729e',square:'#7c76df',rectangle:'#4cbbae',pentagon:'#69b9e9',hexagon:'#b989df'}[id]);let h=size/2;let body=id==='circle'?`<circle cx="${x}" cy="${y}" r="${h}"/>`:id==='square'?`<rect x="${x-h}" y="${y-h}" width="${size}" height="${size}" rx="8"/>`:id==='rectangle'?`<rect x="${x-h*1.2}" y="${y-h*.65}" width="${size*1.2}" height="${size*.65}" rx="6"/>`:`<polygon points="${Array.from({length:({triangle:3,pentagon:5,hexagon:6}[id]||3)},(_,i)=>{let a=i*2*Math.PI/({triangle:3,pentagon:5,hexagon:6}[id]||3)-Math.PI/2;return `${x+Math.cos(a)*h},${y+Math.sin(a)*h}`;}).join(' ')}" stroke-linejoin="round"/>`;return `<g fill="${color}" stroke="#ffffff" stroke-width="3">${body}</g>`;}
function tent(x,y,s=1){return `<g transform="translate(${x} ${y}) scale(${s})"><path d="M-110 0Q-45-10 0-100 45-10 110 0Z" fill="#fff7d9"/><path d="M-110 0Q-45-10 0-100-23-14-43 0ZM0-100Q45-10 110 0H43Q23-14 0-100Z" fill="#ef789f"/><path d="M-100 0H100V95H-100Z" fill="#fff6db"/><path d="M-100 0H-65V95H-100ZM-30 0H5V95H-30ZM40 0H75V95H40Z" fill="#f190ad"/><path d="M-36 95V52Q0 12 36 52V95Z" fill="#60469d"/><path d="M-110 0H110" stroke="#5e4499" stroke-width="5"/><path d="M0-100V-135L42-119 0-108" fill="#ffcb56" stroke="#5e4499" stroke-width="3"/>${star(0,-38,1.25)}</g>`;}
function clock(x=200,y=110,hour=3,minute=0,r=75){let ha=(hour%12+minute/60)*Math.PI/6,ma=minute*Math.PI/30;return `<g><circle cx="${x}" cy="${y}" r="${r+8}" fill="#6650b3"/><circle cx="${x}" cy="${y}" r="${r}" fill="#fff9e8"/>${Array.from({length:12},(_,i)=>{let a=(i+1)*Math.PI/6;return `<text x="${x+Math.sin(a)*r*.8}" y="${y-Math.cos(a)*r*.8+5}" text-anchor="middle" font-size="${r*.19}" font-weight="800" fill="#4c3a7c">${i+1}</text>`;}).join('')}<path d="M${x} ${y}L${x+Math.sin(ha)*r*.46} ${y-Math.cos(ha)*r*.46}" stroke="#5c469d" stroke-width="8" stroke-linecap="round"/><path d="M${x} ${y}L${x+Math.sin(ma)*r*.65} ${y-Math.cos(ma)*r*.65}" stroke="#ef7b9c" stroke-width="5" stroke-linecap="round"/><circle cx="${x}" cy="${y}" r="6" fill="#ffbe4e"/></g>`;}
function scene(id){let inner='';
 if(id==='cars')inner=`<ellipse cx="200" cy="182" rx="174" ry="32" fill="#e29536" opacity=".25"/><path d="M35 55Q200-15 365 55" fill="none" stroke="#9f6945" stroke-width="3"/>${Array.from({length:10},(_,i)=>`<circle cx="${40+i*35}" cy="${52-Math.sin(i/9*Math.PI)*35}" r="5" fill="${i%2?'#fff8d9':'#ff6e8b'}"/>`).join('')}${car(121,139,'#f67b8f')}${car(285,155,'#7861c9')}${star(210,107,.8)}${star(224,83,.5,'#fff4cc')}`;
 if(id==='clowns')inner=`<ellipse cx="200" cy="194" rx="143" ry="20" fill="#c46e94" opacity=".25"/><path d="M45 50H355M80 50V195M320 50V195" stroke="#b3608e" stroke-width="4"/><path d="M35 40H365L340 67H60Z" fill="#fff1cd"/>${clown(150,113,.8)}${clown(260,108,.9,'#8d84e4')}${star(85,100,.7)}${star(332,120,.7)}`;
 if(id==='factory')inner=`<ellipse cx="210" cy="200" rx="155" ry="14" fill="#6d5cab" opacity=".3"/><path d="M115 93V48H150V93" fill="#7866b4"/><circle cx="132" cy="31" r="15" fill="#eee6ff"/><circle cx="153" cy="16" r="11" fill="#eee6ff"/><rect x="85" y="82" width="208" height="104" rx="28" fill="#7363bb" stroke="#53428e" stroke-width="3"/><rect x="111" y="101" width="100" height="59" rx="18" fill="#d8f6ea"/>${eyes(162,120)}<circle cx="251" cy="116" r="11" fill="#ffd06b"/><circle cx="251" cy="151" r="11" fill="#ff97bc"/><path d="M52 185H345" stroke="#59478b" stroke-width="20" stroke-linecap="round"/>${[65,100,135,170,205,240,275,310,340].map(x=>`<circle cx="${x}" cy="185" r="5" fill="#c8baf1"/>`).join('')}${star(53,153,.9)}${star(324,153,.9)}`;
 if(id==='patterns')inner=`<path d="M50 192H350" stroke="#3fae9d" stroke-width="12" stroke-linecap="round"/>${shape('square',116,158,64)}${shape('triangle',188,158,68)}${shape('circle',258,158,60)}${shape('triangle',151,100,66)}${shape('square',226,95,65)}${shape('pentagon',190,46,55)}${star(70,90,.7,'#ffefb0')}${star(324,70,.9,'#fff0b0')}`;
 if(id==='bubbles')inner=`${[[105,90,52,'4'],[215,143,60,'8'],[309,63,40,'2']].map(([x,y,r,n])=>`<circle cx="${x}" cy="${y}" r="${r}" fill="#e4f9ff" fill-opacity=".65" stroke="#fff" stroke-width="3"/><path d="M${x-r*.65} ${y-r*.25}q2-22 22-24" stroke="#fff" stroke-width="6" stroke-linecap="round" fill="none"/><text x="${x}" y="${y+15}" font-size="45" text-anchor="middle" fill="#5181b9" font-weight="900">${n}</text>`).join('')}<circle cx="310" cy="167" r="19" fill="#ecfaff" opacity=".7"/>${star(158,36,.65,'#fff0b0')}`;
 if(id==='clock')inner=`${clock(201,111,3,0,75)}${star(81,56,.9)}${star(325,155,1.1)}<path d="M162 198h78" stroke="#a37948" stroke-width="8" stroke-linecap="round"/><path d="M184 191l-7 13M219 191l7 13" stroke="#6650b3" stroke-width="8"/>`;
 if(id==='tickets')inner=`<path d="M105 85h185v111H105Z" fill="#fff4ce" stroke="#597b48" stroke-width="3"/><path d="M83 85 115 35H280L311 85Z" fill="#f697aa"/><path d="M115 35h33l-15 50H97ZM181 35h33v50h-40ZM247 35h33l20 50h-34Z" fill="#fff4da"/><rect x="137" y="104" width="119" height="63" rx="20" fill="#658b6d"/><text x="197" y="145" text-anchor="middle" font-size="30" font-weight="900" fill="#fff4d3">R$</text><path d="M90 196H306" stroke="#597b48" stroke-width="8" stroke-linecap="round"/>${star(65,133,.9)}${star(335,83,.7)}`;
 if(id==='shapes')inner=`${tent(201,123,.65)}${shape('circle',72,147,48)}${shape('triangle',329,159,63)}${shape('square',312,66,46)}${star(91,65,.85)}`;
 return svg(inner);
}
root.ParkArt={svg,star,eyes,car,clown,shape,tent,clock,scene};
})(window);
